package cn.medreminder.app;

import android.app.*;import android.content.*;import android.net.Uri;import android.os.Build;import java.text.SimpleDateFormat;import java.util.*;

/** One-shot, medicine-independent receiver delivery diagnostic. */
public final class AlarmSelfTest {
 public static final String ACTION="cn.medreminder.app.BACKGROUND_TEST", PREF="alarm_self_test";
 private static final String CHANNEL="background_test"; private static final int ID=0x4d4535; private static volatile boolean foreground;
 private AlarmSelfTest(){}
 public static void visibility(boolean value){foreground=value;}
 public static void appEntry(Context c,String kind){visibility(true);SharedPreferences p=c.getSharedPreferences(PREF,0);AlarmSelfTestLifecycle s=load(p).foregroundEntry(System.currentTimeMillis());save(p,s);event(p,kind,s.due,System.currentTimeMillis(),true);}
 public static void foregroundLaunch(Context c){appEntry(c,"app_resumed");}
 public static void reschedule(Context c,String reason){SharedPreferences p=c.getSharedPreferences(PREF,0);event(p,"reschedule_"+reason,p.getLong("due",0),System.currentTimeMillis(),foreground);}
 public static void start(Context context){Context c=context.getApplicationContext();SharedPreferences p=c.getSharedPreferences(PREF,0);AlarmSelfTestLifecycle prior=load(p);cancelAlarm(c,prior.generation);cancelNotification(c);long generation=prior.generation+1,due=System.currentTimeMillis()+60000;Intent i=new Intent(c,ReminderReceiver.class).setAction(ACTION).setData(Uri.parse("medreminder://background-test/"+generation)).putExtra("generation",generation).putExtra("due",due);PendingIntent pi=PendingIntent.getBroadcast(c,ID,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);boolean exact=Build.VERSION.SDK_INT<31||am.canScheduleExactAlarms();String outcome=AlarmClockRegistration.register(exact,new AlarmClockRegistration.Registrar(){public void alarmClock(){Intent show=new Intent(c,MainActivity.class).setAction("cn.medreminder.app.SHOW_TEST");PendingIntent sp=PendingIntent.getActivity(c,ID,show,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);am.setAlarmClock(new AlarmManager.AlarmClockInfo(due,sp),pi);}public void exactIdle(){am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,due,pi);}public void inexact(){am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,due,pi);}});AlarmSelfTestLifecycle next=prior.start(generation,due);if("failed".equals(outcome))next=AlarmSelfTestLifecycle.restore(generation,due,"failed",0,"",-1,0);save(p,next);p.edit().putString("mode",outcome).apply();event(p,"scheduled",due,System.currentTimeMillis(),foreground);}
 public static void cancel(Context context){Context c=context.getApplicationContext();SharedPreferences p=c.getSharedPreferences(PREF,0);AlarmSelfTestLifecycle prior=load(p);cancelAlarm(c,prior.generation);cancelNotification(c);AlarmSelfTestLifecycle next=prior.cancel();save(p,next);p.edit().remove("mode").apply();event(p,"cancelled",0,System.currentTimeMillis(),foreground);}
 private static void cancelNotification(Context c){try{((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(ID);}catch(RuntimeException ignored){}}
 private static void cancelAlarm(Context c,long g){if(g<=0)return;Intent i=new Intent(c,ReminderReceiver.class).setAction(ACTION).setData(Uri.parse("medreminder://background-test/"+g));PendingIntent pi=PendingIntent.getBroadcast(c,ID,i,PendingIntent.FLAG_NO_CREATE|PendingIntent.FLAG_IMMUTABLE);if(pi!=null){((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).cancel(pi);pi.cancel();}}
 private static AlarmSelfTestLifecycle load(SharedPreferences p){return AlarmSelfTestLifecycle.restore(p.getLong("generation",0),p.getLong("due",0),p.getString("state","idle"),p.getLong("actual",0),p.getString("notify",""),p.getInt("receiver_foreground",-1),p.getLong("first_return",0));}
 private static void save(SharedPreferences p,AlarmSelfTestLifecycle s){SharedPreferences.Editor e=p.edit().putLong("generation",s.generation).putLong("due",s.due).putString("state",s.state).putLong("actual",s.actual).putString("notify",s.notification).putInt("receiver_foreground",s.receiverForeground).putLong("first_return",s.firstReturn);e.apply();}
 public static boolean accepts(long callbackGeneration,long callbackDue,long currentGeneration,long currentDue,String state){return AlarmSelfTestLifecycle.restore(currentGeneration,currentDue,state,0,"",-1,0).accepts(callbackGeneration,callbackDue,System.currentTimeMillis());}
 public static boolean acceptsAt(long callbackGeneration,long callbackDue,long currentGeneration,long currentDue,String state,long actual){return AlarmSelfTestLifecycle.restore(currentGeneration,currentDue,state,0,"",-1,0).accepts(callbackGeneration,callbackDue,actual);}
 public static String visibleState(String state,long due,long now){return AlarmSelfTestLifecycle.restore(0,due,state,0,"",-1,0).displayState(now);}
 public static void received(Context c,Intent i){SharedPreferences p=c.getSharedPreferences(PREF,0);AlarmSelfTestLifecycle old=load(p);long g=i.getLongExtra("generation",-1),due=i.getLongExtra("due",-1),now=System.currentTimeMillis();AlarmSelfTestLifecycle next=old.received(g,due,now,foreground);if(next==old)return;save(p,next);event(p,"receiver_fired",due,now,foreground);try{NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel(CHANNEL,c.getString(R.string.self_test_channel),NotificationManager.IMPORTANCE_DEFAULT));boolean enabled=Build.VERSION.SDK_INT<24||nm.areNotificationsEnabled();if(Build.VERSION.SDK_INT>=33)enabled&=c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")==android.content.pm.PackageManager.PERMISSION_GRANTED;if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=nm.getNotificationChannel(CHANNEL);enabled&=ch!=null&&ch.getImportance()!=NotificationManager.IMPORTANCE_NONE;}if(!enabled){next=next.notification("blocked");save(p,next);event(p,"notification_blocked",due,now,foreground);return;}Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL):new Notification.Builder(c);b.setSmallIcon(R.drawable.ic_stat_notification).setContentTitle(c.getString(R.string.self_test_title)).setContentText(c.getString(R.string.self_test_text)).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE);nm.notify(ID,b.build());next=next.notification("submitted");save(p,next);event(p,"notification_submitted",due,now,foreground);}catch(RuntimeException e){next=next.notification("failed");save(p,next);event(p,"notification_failed",due,now,foreground);}}
 private static String stateLabel(Context c,String state,long due,long now){String key=("pending".equals(state)&&due>0&&now>due)?"not_received":state;int id;if("pending".equals(key))id=R.string.self_test_state_pending;else if("fired".equals(key))id=R.string.self_test_state_fired;else if("cancelled".equals(key))id=R.string.self_test_state_cancelled;else if("failed".equals(key))id=R.string.self_test_state_failed;else if("not_received".equals(key))id=R.string.self_test_state_not_received;else id=R.string.self_test_state_idle;return c.getString(id);}
 private static String noticeLabel(Context c,String value){int id="submitted".equals(value)?R.string.self_test_notice_submitted:"blocked".equals(value)?R.string.self_test_notice_blocked:"failed".equals(value)?R.string.self_test_notice_failed:R.string.self_test_notice_unknown;return c.getString(id);}
 public static String status(Context c){SharedPreferences p=c.getSharedPreferences(PREF,0);AlarmSelfTestLifecycle s=load(p);long now=System.currentTimeMillis();StringBuilder b=new StringBuilder(c.getString(R.string.self_test_status,stateLabel(c,s.state,s.due,now)));if(s.due>0)b.append(c.getString(R.string.self_test_scheduled_at,time(s.due)));if(s.actual>0){b.append(c.getString(R.string.self_test_receiver_at,time(s.actual),noticeLabel(c,s.notification)));if(s.actual>=s.due)b.append(c.getString(R.string.self_test_late,duration(c,s.actual-s.due)));if(s.firstReturn>0)b.append(c.getString(s.actual<s.firstReturn?R.string.self_test_receiver_first:R.string.self_test_foreground_first));}if(p.contains("mode"))b.append(c.getString(R.string.self_test_registration,registrationLabel(c,p.getString("mode",""))));return b.append(c.getString(R.string.self_test_footer_joiner)).append(c.getString(R.string.self_test_footer)).toString();}
 private static String registrationLabel(Context c,String mode){int id="alarm_clock".equals(mode)?R.string.self_test_mode_alarm_clock:"exact_idle".equals(mode)?R.string.self_test_mode_exact_idle:"inexact".equals(mode)?R.string.self_test_mode_inexact:"failed".equals(mode)?R.string.self_test_mode_failed:R.string.alarm_code_unknown;return c.getString(id);}
 private static String eventLabel(Context c,String event){if("scheduled".equals(event))return c.getString(R.string.self_event_scheduled);if("cancelled".equals(event))return c.getString(R.string.self_event_cancelled);if("receiver_fired".equals(event))return c.getString(R.string.self_event_receiver);if("notification_blocked".equals(event))return c.getString(R.string.self_event_blocked);if("notification_submitted".equals(event))return c.getString(R.string.self_event_submitted);if("notification_failed".equals(event))return c.getString(R.string.self_event_failed);if(event.startsWith("reschedule_"))return c.getString(R.string.self_event_rescheduled);if("app_launch".equals(event))return c.getString(R.string.self_event_app_launch);if("app_resumed".equals(event))return c.getString(R.string.self_event_app_resumed);return c.getString(R.string.alarm_code_unknown);}
 public static String events(Context c){String raw=c.getSharedPreferences(PREF,0).getString("events","");if(raw.isEmpty())return c.getString(R.string.self_test_no_events);StringBuilder out=new StringBuilder();for(String row:raw.split("\n")){String[] fields=row.split(" \\| ",4);if(fields.length==4){if(out.length()>0)out.append('\n');String planned=fields[1].startsWith("planned=")?fields[1].substring(8):"-",actual=fields[2].startsWith("event=")?fields[2].substring(6):"-";String side="foreground".equals(fields[3])?c.getString(R.string.self_event_foreground):c.getString(R.string.self_event_background);out.append(c.getString(R.string.self_event_prefix,eventLabel(c,fields[0]),planned,actual,side));}}return c.getString(R.string.self_test_recent_events,out.toString());}
 private static String time(long t){return new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS",Locale.ROOT).format(new Date(t));}
 private static String duration(Context c,long ms){return c.getString(R.string.self_test_duration_seconds,ms/1000,ms%1000);}
 private static void event(SharedPreferences p,String type,long due,long actual,boolean fg){String old=p.getString("events","");String row=type+" | planned="+(due>0?time(due):"-")+" | event="+time(actual)+" | "+(fg?"foreground":"background");String[] a=old.isEmpty()?new String[0]:old.split("\\n");StringBuilder b=new StringBuilder();for(int i=Math.max(0,a.length-31);i<a.length;i++)b.append(a[i]).append('\n');b.append(row);p.edit().putString("events",b.toString()).apply();}
}
